/* ---------------------------------------------------------------
   TRAITS - five fighters share a data deck, so the deck alone cannot
   separate them. Their dossier ratings can: power, guard, air and
   stamina are derived from attributes that are already unique per
   fighter. Traits are a design layer, not part of the card record.
   --------------------------------------------------------------- */
const TRAITS={};
function traitsOf(fid){
  if(TRAITS[fid]) return TRAITS[fid];
  const b=bioOf(fid);
  let t;
  if(!b) t={pow:1,def:1,air:1,hp:100,foc:3,tag:"BALANCED"};
  else{
    const A=b.a;
    const pw=A[0]*.55+A[4]*.45, df=A[5]*.6+A[11]*.4, ar=A[1]*.6+A[3]*.4;
    t={ pow:+(1+(pw-85)/170).toFixed(3),
        def:+(1+(df-83)/180).toFixed(3),
        air:+(1+(ar-83)/170).toFixed(3),
        hp:Math.round(95+(A[2]-79)*.55),
        foc:A[1]>=90?4:A[1]>=75?3:2, tag:"" };
    const m=Math.max(t.pow,t.def,t.air);
    t.tag = m===t.pow?"PRESSURE" : m===t.def?"WALL" : "AERIAL";
    if(Math.max(t.pow,t.def,t.air)-Math.min(t.pow,t.def,t.air)<.05) t.tag="BALANCED";
  }
  /* The dossier says what a fighter IS. The tuning table says how far the
     roster audit had to nudge them to make the fight fair. Kept separate and
     applied here so the attributes above stay honest and the balance thumb
     stays readable - see tools/tune-roster.js. */
  const k=(typeof traitTuneFor==="function")?traitTuneFor(fid):1;
  if(k!==1){
    t={pow:+(t.pow*k).toFixed(3), def:+(t.def*(1+(k-1)*.6)).toFixed(3),
       air:+(t.air*k).toFixed(3), hp:Math.round(t.hp*(1+(k-1)*.5)),
       foc:t.foc, tag:t.tag};
  }
  return (TRAITS[fid]=t);
}
const hpOf=fid=>traitsOf(fid).hp;

/* ---- src/data/roster-tune.js ---- */
/* =====================================================================
   Aqua Zero Heavens Arena - roster balance corrections
   Luminara Digital

   GENERATED by tools/tune-roster.js - do not hand-edit, re-run the tuner.

   A dossier is what the book says about a fighter. It is not a promise
   that they are competitive, and an audit of the whole roster fighting
   itself found a 65-point spread between the best and worst - over half
   the roster was a trap.

   These are per-fighter corrections applied on top of the dossier-derived
   traits. They sit here, in the open, rather than being smuggled into the
   dossiers: the attributes stay honest and the balance thumb is readable.

   converged over 7 tuning rounds against tools/audit-balance.js
   ===================================================================== */
const TRAIT_TUNE = {"0":0.9777,"1":0.8865,"2":0.9744,"3":1.0593,"4":1.163,"5":0.9327,"6":0.9867,"7":0.9315,"8":0.9093,"9":0.9902,"11":0.8462,"12":0.9702,"13":0.8343,"14":1.0409,"15":0.8466,"16":1.0916,"17":0.8813,"18":0.8748,"19":0.9293,"20":0.7625,"21":0.8744,"22":0.9812,"23":1.0375,"24":0.8607};
const traitTuneFor = (fid) => TRAIT_TUNE[fid] || 1;

