function howTopic(){ return HOW_TOPICS[G.howTopic]||HOW_TOPICS.general; }
function howPages(){ return howTopic().pages; }
function rHow(){
  bgFill("#0e1014","#08090b");
  const topic=howTopic(), pages=topic.pages;
  if(G.how>=pages.length) G.how=0;
  const pg=pages[G.how];
  txt(topic.name,W/2,44,22,INK,"center",800);
  pg.forEach((c,ci)=>{
    const x=ci?W/2+40:70;
    txt(c[0],x,80,14,RED,"left",800);
    c[1].forEach((l,i)=>txt(l,x,104+i*21,11.5,INK,"left",600));
  });
  txt("EVERY FIGHTER IS ONE 75-BYTE RECORD - FIFTEEN CARDS AND THE ORDER THEY ARRIVE IN",W/2,496,10.5,DIM,"center",600);
  txt((G.how?"< PREV   ":"")+"PAGE "+(G.how+1)+"/"+pages.length+"   "
      +(G.how<pages.length-1?"A - NEXT >":"A - BACK")+"   B - BACK",W/2,518,12,INK,"center",800);
}
/* One list, read by both the renderer and the key handler, so a row can never
   be drawn in one place and acted on in another. */
function optionRows(){
  const hasBackup=!!latestBackup(readBackupVault(localStorage));
  const rows=[
    {id:"diff",    label:"DIFFICULTY",     value:diff().name,                 blurb:diff().blurb},
    {id:"sound",   label:"SOUND",          value:SAVE.sound?"ON":"OFF",       blurb:"everything - score, bell, crowd, hits"},
    {id:"music",   label:"MUSIC",          value:SAVE.music?"ON":"OFF",       blurb:"entrance themes, the fight score, the bell"},
    {id:"motion",  label:"MOTION",         value:SAVE.motion?"ON":"OFF",      blurb:"screen shake and impact sparks"},
    {id:"deck",    label:"DATA DECK",      value:SAVE.dataDeck?"SHOW":"HIDDEN", blurb:"show fight data table / hidden"},
    {id:"name",    label:"FIGHTER NAME",   value:SAVE.name||"CHALLENGER",     blurb:"your name on the ladder and boards"},
    {id:"export",  label:"EXPORT SAVE",    value:"...",                       blurb:"download azha-save.json - a portable copy"},
    {id:"import",  label:"IMPORT SAVE",    value:"...",                       blurb:"replace progress from a JSON file"},
    {id:"restore", label:"RESTORE BACKUP", value:G.restoreArm?"PRESS A AGAIN":(hasBackup?"...":"NONE"),
     blurb:G.restoreArm?"loads the latest automatic snapshot":(hasBackup?"last automatic snapshot - press A twice":"no automatic snapshot yet")},
    {id:"erase",   label:"ERASE SAVE",     value:G.eraseArm?"PRESS A AGAIN":"...",
     blurb:G.eraseArm?"this wipes mastery, records, run and local backups":"mastery, records, options, run and backups"},
  ];
  if(!cloudConfigured()){
    rows.push({id:"cloud", label:"CLOUD", value:"OFF",
      blurb:"optional centralized sync - not required for AGPL/TON play"});
  }else if(!cloudReadSession(localStorage)){
    rows.push(
      {id:"cloud-up", label:"CLOUD SIGN UP", value:"...",
       blurb:"optional email account (centralized)"},
      {id:"cloud-in", label:"CLOUD SIGN IN", value:"...",
       blurb:"optional - prefer TON wallet for decentralized play"}
    );
  }else{
    rows.push(
      {id:"cloud-sync", label:"CLOUD SYNC", value:cloudStatusLabel(localStorage),
       blurb:"pull or push - higher rev wins"},
      {id:"cloud-out", label:"CLOUD SIGN OUT", value:"...",
       blurb:"keeps the local save; clears the cloud session"}
    );
  }
  rows.push({
    id:"ton",
    label:"TON WALLET",
    value:tonStatusLabel(localStorage),
    blurb:tonCanConnect()
      ? (tonReadWallet(localStorage)?"A disconnects - identity via TON Connect":"A opens TON Connect - needs https manifest")
      : "set GitHub Pages URL / AZHA_TON_MANIFEST_URL then rebuild"
  });
  rows.push({id:"back", label:"BACK", value:"", blurb:"return to the menu"});
  return rows;
}
function rOptions(){
  rTitleBackdrop();
  const rows=optionRows();
  if(G.optSel>=rows.length) G.optSel=0;
  const panelH=Math.min(460, 120+rows.length*32);
  panel(W/2-260,72,520,panelH);
  txt("OPTIONS",W/2,100,14,DIM,"center",800);
  rows.forEach((r,i)=>{
    const y=124+i*30, on=i===G.optSel;
    const armed=(r.id==="erase"&&G.eraseArm)||(r.id==="restore"&&G.restoreArm);
    if(on){ cx.fillStyle="rgba(224,58,47,.14)"; cx.fillRect(W/2-242,y-14,484,28); }
    txt(r.label,W/2-228,y,12,on?RED:INK,"left",800);
    txt(r.value,W/2+228,y,12,armed?RED:GOLD,"right",800);
    if(on) txt(r.blurb,W/2-228,y+11,9,DIM,"left",600);
    hot(W/2-242,y-14,484,28,()=>{ G.optSel=i; },()=>{ G.optSel=i; onKey("a"); });
  });
  txt("< > CHANGE    A - SELECT    B - BACK",W/2,512,11,DIM,"center",600);
}
/* Two boards: the ladder (you among every graded opponent you have faced)
   and the hall of records (career bests worth chasing). */
function rBoard(){
  bgFill("#101318","#07080a");
  txt("LEADERBOARDS",W/2,44,26,RED,"center",800,true);
  const tabs=["KYU / DAN LADDER","HALL OF RECORDS"];
  tabs.forEach((s,i)=>{
    const on=(G.boardTab|0)===i, x=W/2+(i?130:-130);
    panel(x-115,58,230,24,on?"rgba(224,58,47,.14)":"rgba(10,11,14,.8)",on?RED:"#252831");
    txt(s,x,74,11,on?INK:DIM,"center",on?800:600);
  });
  if((G.boardTab|0)===0){
    const rows=rankApi().getLeaderboard(12).data.map(r=>({
      name:r.playerId===YOU?(SAVE.name||"CHALLENGER")+"  (YOU)"
           :r.playerId.slice(0,4)==="cpu:"?FIGHTERS[+r.playerId.slice(4)].name:r.playerId,
      you:r.playerId===YOU, rank:r.rank, pts:+r.points.toFixed(1), w:r.wins, l:r.losses}));
    if(!rows.some(r=>r.you)){
      const me=myRanking();
      rows.push({name:(SAVE.name||"CHALLENGER")+"  (YOU)",you:true,rank:me.rank,pts:me.promotionPoints,w:me.wins,l:me.losses});
    }
    txt("#",84,110,10,DIM,"left",700); txt("FIGHTER",110,110,10,DIM,"left",700);
    txt("GRADE",470,110,10,DIM,"left",700); txt("PTS",700,110,10,DIM,"right",700);
    txt("W-L",800,110,10,DIM,"right",700);
    rows.forEach((r,i)=>{
      const y=134+i*26;
      if(r.you){ cx.fillStyle="rgba(34,211,238,.08)"; cx.fillRect(70,y-15,W-140,22); }
      txt(i+1,84,y,11,r.you?AQUA:DIM,"left",700);
      txt(r.name,110,y,12,r.you?AQUA:INK,"left",r.you?800:600);
      txt(r.rank.title.toUpperCase(),470,y,11,r.rank.color,"left",800);
      txt(r.pts,700,y,11,INK,"right",600);
      txt(r.w+"-"+r.l,800,y,11,DIM,"right",600);
    });
    if(rows.length<=1) txt("FIGHT RANKED MATCHES TO FILL THE LADDER",W/2,240,12,DIM,"center",600);
  } else {
    const R=SAVE.rec, best=[
      ["MASTERED FIGHTERS",SAVE.unlocked.length+" / "+FIGHTERS.length],
      ["CAREER WINS",R.wins||0],
      ["PERFECT VICTORIES",R.perfect||0],
      ["BEST LADDER GRADE",rankByIndex(rankApi().getPlayerRanking(YOU).data.peakRank.index).title.toUpperCase()],
      ["ADVENTURES CLEARED",R.clears||0],
      ["BEST SURVIVAL STREAK",R.survBest||0],
      ["NEW GAME+ CYCLES",R.ngplus||0],
      ["DUELS FOUGHT",R.duels||0],
    ];
    best.forEach((b,i)=>{
      const x=i%2?W/2+30:90, y=140+Math.floor(i/2)*54;
      panel(x,y-24,W/2-120,40,"rgba(10,11,14,.85)","#252831");
      txt(b[0],x+14,y-4,10,DIM,"left",700);
      txt(b[1],x+W/2-134,y-1,15,GOLD,"right",800);
    });
  }
  txt("LEFT/RIGHT - SWITCH BOARD      A - BACK",W/2,H-16,10.5,DIM,"center",600);
}
