  const oname=f.boss?FIGHTERS[BOSS_ID].name:(f.tf?"AZX FORCE":FIGHTERS[f.id].name);
  txt(oname,720,70,16,f.boss?RED:INK,"center",800);
  const ohp=f.boss?Math.round((150+ng*45)*dm.hp)
        :f.tf?Math.round((40+a.stage*10+ng*12)*dm.hp)
        :Math.round((85+a.stage*14+ng*18)*dm.hp);
  txt((f.boss?"":"LV "+f.lv+"  -  ")+ohp+" HP"+(f.boss?" - 5 SEALED CARDS":""),720,92,11,DIM,"center",600);
