function rangeStrip(d){
  const w=94, gap=6, total=RANGE_ORDER.length*(w+gap)-gap, ox=(W-total)/2;
  RANGE_ORDER.forEach((r,i)=>{
    const x=ox+i*(w+gap), on=r===d.range;
    panel(x,104,w,22, on?"rgba(34,211,238,.16)":"rgba(10,11,14,.75)", on?AQUA:"#252831");
    txt(RANGE_LABEL[r],x+w/2,119,10,on?AQUA:"#5d626c","center",on?800:600);
  });
  const mine=homeRanges(d.p.discs);
  txt(describePosition(d),W/2,152,10,d.cornered==="p"?RED:(d.cornered==="e"?GRN:DIM),"center",800);
  txt(mine.indexOf(d.range)>=0?"YOUR RANGE":"OUT OF YOUR RANGE",W/2,138,9,
      mine.indexOf(d.range)>=0?GRN:RED,"center",700);
  /* the pressure ledger, on screen at last. The corner was always earned
     over two or three turns of landed work - now you can watch it being
     earned, and watch it being taken back. */
  const m=d.press;
  if(m&&m.n>0.05){
    const bw=150,bx=W/2-bw/2,by=158;
    const fr=Math.min(1,m.n/PRESS_STEP), hotFr=fr>=.8;
    panel(bx,by,bw,8,"#0a0b0e",hotFr?(m.by==="p"?GRN:RED):"#2a2d35");
    cx.fillStyle=m.by==="p"?"rgba(155,232,155,.85)":"rgba(224,58,47,.85)";
    cx.fillRect(bx+1,by+1,(bw-2)*fr,6);
    txt((m.by==="p"?"YOU ARE WALKING THEM DOWN":"THEY ARE WALKING YOU DOWN")
        +(hotFr?" - ONE MORE":""),W/2,180,8,m.by==="p"?GRN:RED,"center",700);
  }
}
