/* mastery and titles land under every result, whatever the mode - this is
   the "that run still counted" moment */
function drawPayout(){
  const P=G.payout;
  if(G.payPurse){
    cx.save();
    cx.fillStyle="rgba(216,162,74,.14)";
    cx.fillRect(W/2-210,H-118,420,24);
    cx.strokeStyle="rgba(216,162,74,.4)";
    cx.lineWidth=1;
    cx.strokeRect(W/2-210.5,H-118.5,421,25);
    txt("FIGHT PURSE: +$"+G.payPurse+(G.payRevenge?"  -  GRUDGE REVENGE BOUNTY":""),W/2,H-105,12,GOLD,"center",800);
    cx.restore();
  }
  if(!P) return;
  if(P.mastery){
    const m=P.mastery;
    txt("+"+m.gained+" MASTERY XP   &middot;   "+m.to.name.toUpperCase()
        +(m.levelled?"   -   NEW BELT UNLOCKED!":""),W/2,H-84,11,m.levelled?GOLD:DIM,"center",m.levelled?800:600);
  }
  if(P.titles&&P.titles.length)
    txt("TITLE EARNED: "+P.titles.map(id=>titleOf(id).toUpperCase()).join(", "),
        W/2,H-64,12,GOLD,"center",800);
}
